import { eventVisualizationsApi } from '@api/event-visualizations-api'
import type { EngineError } from '@api/parse-engine-error'
import {
    preparePayloadForSave,
    preparePayloadForSaveAs,
} from '@dhis2/analytics'
import { useAlert } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { useAppDispatch, useAppSelector } from '@hooks'
import { logger } from '@modules/logger'
import {
    getSaveableVisualization,
    getVisualizationState,
    isCurrentVisualizationPersisted,
    isVisualizationEmpty,
    isVisualizationPersistable,
} from '@modules/visualization/state'
import {
    getCurrentVis,
    setCurrentVisNameDescription,
} from '@store/current-vis-slice'
import { setNavigationState } from '@store/navigation-slice'
import { getSavedVis, setSavedVisNameDescription } from '@store/saved-vis-slice'
import { tLoadSavedVisualization } from '@store/thunks'
import type { SavedVisualization } from '@types'
import { useCallback, useMemo } from 'react'

export const useToolbarActions = () => {
    const dispatch = useAppDispatch()

    const currentVis = useAppSelector(getCurrentVis)
    const savedVis = useAppSelector(getSavedVis)

    const { show: showAlert } = useAlert(
        ({ message }) => message,
        ({ options }) => options
    )

    const isSaveEnabled = useMemo(() => {
        if (!isVisualizationPersistable(currentVis)) {
            return false
        }
        switch (getVisualizationState(savedVis, currentVis)) {
            case 'UNSAVED':
                // Brand-new vis — no existing record to overwrite; Save
                // routes through the SaveAs dialog to create the first
                // persisted copy.
                return true
            case 'DIRTY':
                // Overwriting an existing saved vis. Requires update access
                // and non-legacy status, both read from savedVis because
                // `toCurrentVis` strips those fields. Re-saving a legacy vis
                // in the new format would break older apps that still read
                // it, so "Save as" is the only allowed path for those.
                return Boolean(savedVis.access?.update) && !savedVis.legacy
            default:
                return false
        }
    }, [currentVis, savedVis])

    const isSaveAsEnabled = useMemo(() => {
        if (!isVisualizationPersistable(currentVis)) {
            return false
        }
        // Save As copies an existing saved visualization under a new name,
        // so it requires a savedVis to copy from. UNSAVED (brand-new) is
        // excluded — there is nothing to copy.
        const state = getVisualizationState(savedVis, currentVis)
        return state === 'SAVED' || state === 'DIRTY'
    }, [currentVis, savedVis])

    const onDelete = useCallback(() => {
        dispatch(setNavigationState({ visualizationId: 'new' }))

        showAlert({
            message: i18n.t('"{{- deletedObject}}" successfully deleted.', {
                deletedObject: savedVis.name,
            }),
            options: {
                success: true,
                duration: 2000,
            },
        })
    }, [dispatch, savedVis.name, showAlert])

    const onError = useCallback(
        (error: EngineError) => {
            logger.error(error)
            let message = error.message || i18n.t('An unknown error occurred.')

            switch (error.errorCode) {
                case 'E4030':
                    message = i18n.t(
                        "This visualization can't be deleted because it is used on one or more dashboards."
                    )
                    break
                case 'E1006':
                    message = i18n.t("You don't have sufficient permissions.")
                    break
                default:
                    break
            }

            const alertLevel = /50\d/.test(String(error.httpStatusCode))
                ? 'error'
                : 'warning'

            showAlert({
                message,
                options: {
                    [alertLevel]: true,
                },
            })
        },
        [showAlert]
    )

    const onNew = useCallback(
        () => dispatch(setNavigationState({ visualizationId: 'new' })),
        [dispatch]
    )

    const onOpen = useCallback(
        (id: string) => {
            if (
                isCurrentVisualizationPersisted(currentVis) &&
                currentVis.id === id
            ) {
                dispatch(
                    tLoadSavedVisualization({ id, updateStatistics: false })
                )
            } else {
                dispatch(setNavigationState({ visualizationId: id }))
            }
        },
        [dispatch, currentVis]
    )

    // Existing visualization
    // the visualization is updated with only name and/or description from the rename dialog
    const onRename = useCallback(
        async ({
            name,
            description,
        }: {
            name?: string
            description?: string
        }) => {
            const { data, error } = await dispatch(
                eventVisualizationsApi.endpoints.renameVisualization.initiate({
                    name,
                    description,
                })
            )

            if (data) {
                // Update current and visualization with edited name/description
                dispatch(setCurrentVisNameDescription(data))
                dispatch(setSavedVisNameDescription(data))

                showAlert({
                    message: i18n.t('Rename successful'),
                    options: {
                        success: true,
                        duration: 2000,
                    },
                })
            } else if (error) {
                showAlert({
                    message: i18n.t('Rename failed'),
                    options: {
                        critical: true,
                    },
                })
            }
        },
        [dispatch, showAlert]
    )

    // Existing visualization
    const onSave = useCallback(async () => {
        if (isVisualizationEmpty(currentVis)) {
            throw new Error('onSave called with an empty visualization')
        }

        const { data, error } = await dispatch(
            eventVisualizationsApi.endpoints.updateVisualization.initiate(
                preparePayloadForSave({
                    visualization: getSaveableVisualization(
                        currentVis as SavedVisualization
                    ),
                })
            )
        )

        if (data && isCurrentVisualizationPersisted(currentVis)) {
            // Reload the saved visualization after saving
            // here we should *not* update statistics
            dispatch(
                tLoadSavedVisualization({
                    id: currentVis.id,
                    updateStatistics: false,
                })
            )
        } else if (error) {
            onError(error as EngineError)
        }
    }, [dispatch, currentVis, onError])

    // New visualization
    // it can be a copy of an existing one, but a new id is returned
    const onSaveAs = useCallback(
        async (nameAndDescription: { name: string; description: string }) => {
            if (isVisualizationEmpty(currentVis)) {
                throw new Error('onSaveAs called with an empty visualization')
            }

            const { data, error } = await dispatch(
                eventVisualizationsApi.endpoints.createVisualization.initiate(
                    preparePayloadForSaveAs({
                        visualization: {
                            ...getSaveableVisualization(
                                currentVis as SavedVisualization
                            ),
                            // XXX: this ideally should be done in preparePayloadForSaveAs
                            subscribers: [],
                        },
                        ...nameAndDescription,
                    })
                )
            )

            if (data) {
                // Navigate to the new visualization
                dispatch(setNavigationState({ visualizationId: data }))
            } else if (error) {
                onError(error as EngineError)
            }
        },
        [dispatch, currentVis, onError]
    )

    return {
        isSaveEnabled,
        isSaveAsEnabled,
        onDelete,
        onError,
        onOpen,
        onNew,
        onRename,
        onSave,
        onSaveAs,
    }
}
